const CAPACITY:usize=super::super::KERNEL_REQUEST_QUEUE_CAPACITY;
#[path="../🧩️compile/🦀️.rs"]
mod compiler;
struct Fields{path:Option<PathBuf>,plugin:Option<String>,app:Option<String>,schema:Option<String>}
impl Fields{const fn empty()->Self{Self{path:None,plugin:None,app:None,schema:None}}fn empty_owner(&self)->bool{self.path.is_none()&&self.plugin.is_none()&&self.app.is_none()&&self.schema.is_none()}}
struct Slot{node:Mutex<Option<Node>>,waiter:Mutex<Option<Waker>>,fields:UnsafeCell<Fields>,compiler_inputs:UnsafeCell<compiler::Inputs>,compiler_output:UnsafeCell<compiler::Output>,compiler_wake:AtomicBool,compiler_cancelled:AtomicBool,compiler_running:AtomicBool,notify_client:AtomicBool,generation:AtomicU64,detached:AtomicBool,published:AtomicBool}
/// 🔐️ Fields mutate only before publication or after primary return and every genuine source loan; Node checkout never aliases those fields.
unsafe impl Sync for Slot{}
impl Slot{const fn empty()->Self{Self{node:Mutex::new(None),waiter:Mutex::new(None),fields:UnsafeCell::new(Fields::empty()),compiler_inputs:UnsafeCell::new(compiler::Inputs::empty()),compiler_output:UnsafeCell::new(compiler::Output::empty()),compiler_wake:AtomicBool::new(false),compiler_cancelled:AtomicBool::new(false),compiler_running:AtomicBool::new(false),notify_client:AtomicBool::new(false),generation:AtomicU64::new(0),detached:AtomicBool::new(false),published:AtomicBool::new(false)}}}
static SLOTS:[Slot;CAPACITY]=[const{Slot::empty()};CAPACITY];
static HOOK:Mutex<Option<WorkerMaintenanceTicket>>=Mutex::new(None);
static COMPILER_HOOK:Mutex<Option<WorkerMaintenanceTicket>>=Mutex::new(None);
static RETRY:AtomicBool=AtomicBool::new(false);
static SCHEDULER_FAILURE:Mutex<Option<WorkerMaintenanceError>>=Mutex::new(None);

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum CreateAppSourceFailureKind{RegistryFull,Maintenance(WorkerMaintenanceError),Source,Stale,Closed,Backend,Cancelled}
pub struct CreateAppSourceFailure{kind:CreateAppSourceFailureKind,owner:Option<CreateAppRequestOwner>,initial:Option<ValueError>}
impl std::fmt::Debug for CreateAppSourceFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{std::fmt::Display::fmt(self,f)}}
impl std::fmt::Display for CreateAppSourceFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{if let Some(error)=self.initial.as_ref(){return write!(f,"{error}")}if let Some(owner)=self.owner.as_ref(){if let Some(result)=with_node(owner.index,owner.generation,|node|{if let Some(error)=node.failures.iter().flatten().next(){return write!(f,"{error}")}if let Some(error)=node.root_failure.as_ref(){return write!(f,"{error:?}")}if let Some(error)=node.caller.original_failure(){return write!(f,"{error:?}")}if let Some(error)=node.caller.original_cleanup_failure(){return write!(f,"{error:?}")}if let Some(task)=node.compiler.as_ref(){write!(f,"{:?}: ",self.kind)?;return task.describe(f)}write!(f,"{:?}",self.kind)}){return result}}write!(f,"{:?}",self.kind)}}

struct Node{caller:NativeFrameCaller,cursor:usize,failed:bool,closed:bool,failures:[Option<ValueError>;4],root_failure:Option<OriginalActorContextError>,compiler:Option<compiler::CompilerTask>}
impl Node{
 fn new(caller:NativeFrameCaller)->Self{Self{caller,cursor:0,failed:false,closed:false,failures:std::array::from_fn(|_|None),root_failure:None,compiler:None}}
 fn room(&self)->bool{self.root_failure.is_none()&&self.failures.iter().any(Option::is_none)}
 fn retain(&mut self,error:ValueError){*self.failures.iter_mut().find(|field|field.is_none()).expect("original CreateApp turn reserved refusal custody")=Some(error);self.failed=true;}
 fn accept<T>(&mut self,call:Result<OriginalActorCall<T,OriginalActorEntryFailure>,ValueError>)->Option<T>{match call{Ok(call)=>match call.result{Ok(value)=>Some(value),Err(OriginalActorEntryFailure::Semantic)=>{self.failed=true;None},Err(OriginalActorEntryFailure::Authority(error))=>{self.retain(error);None}},Err(error)=>{self.retain(error);None}}}
 fn receive(&mut self,slot:&Slot,input:CreateAppBorrowed<'_>){
  if self.failed||!self.room()||!self.caller.ready()||slot.published.load(Ordering::Acquire){return}
  let fields=unsafe{&mut*slot.fields.get()};let cursor=self.cursor;
  if cursor==4{let mut output=None;let call=self.caller.dispatch_step(|cx|admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:size_of::<bool>(),capacity_bytes:0,release_bytes:0,depth:1},|_|Ok((true,RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<bool>(),..Default::default()}))));if self.accept(call)==Some(true){slot.published.store(true,Ordering::Release);}return}
  let data=if cursor==0{input.path.as_os_str().as_encoded_bytes()}else{[input.plugin,input.app,input.schema][cursor-1].as_bytes()};let length=data.len();let demand=OriginalConstructionDemand{items:1,copy_bytes:length,capacity_bytes:length,release_bytes:0,depth:1};
  let call=if cursor==0{self.caller.dispatch_step(|cx|admit_original_construction(cx,&mut fields.path,demand,|_|{let mut bytes=Vec::new();bytes.try_reserve_exact(length).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"CreateApp original path allocation refused"))?;bytes.extend_from_slice(data);let capacity=bytes.capacity();let path=PathBuf::from(unsafe{std::ffi::OsString::from_encoded_bytes_unchecked(bytes)});Ok((path,RetainedCloneProgress{copied_items:1,copied_bytes:length,retained_capacity_bytes:capacity,..Default::default()}))}))}
  else{let output=match cursor{1=>&mut fields.plugin,2=>&mut fields.app,_=>&mut fields.schema};self.caller.dispatch_step(|cx|admit_original_construction(cx,output,demand,|_|{let mut text=String::new();text.try_reserve_exact(length).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"CreateApp original text allocation refused"))?;text.push_str(std::str::from_utf8(data).expect("borrowed CreateApp text remains UTF8"));let capacity=text.capacity();Ok((text,RetainedCloneProgress{copied_items:1,copied_bytes:length,retained_capacity_bytes:capacity,..Default::default()}))}))};
  if self.accept(call)==Some(true){self.cursor+=1;slot.notify_client.store(true,Ordering::Release);}
 }
 fn close_one(&mut self,slot:&Slot){
  if !self.room(){return}if !self.caller.original_loans_are_returned(){return}
  let fields=unsafe{&mut*slot.fields.get()};
  if let Some(path)=fields.path.as_ref(){let demand=RetirementDemand{copy_bytes:size_of::<Option<PathBuf>>(),release_bytes:path.capacity(),depth:1,..Default::default()};let call=self.caller.dispatch_cleanup_step(|cx|close_original_retained_step(cx,demand,|_|{fields.path.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))}));self.accept(call);return}
  for text in [&mut fields.plugin,&mut fields.app,&mut fields.schema]{if let Some(value)=text.as_ref(){let demand=RetirementDemand{copy_bytes:size_of::<Option<String>>(),release_bytes:value.capacity(),depth:1,..Default::default()};let call=self.caller.dispatch_cleanup_step(|cx|close_original_retained_step(cx,demand,|_|{text.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))}));self.accept(call);return}}
  if let Some(index)=self.failures.iter().position(Option::is_some){let release=match &self.failures[index].as_ref().unwrap().message{std::borrow::Cow::Owned(text)=>text.capacity(),_=>0};if !self.caller.ready(){if release==0{self.failures[index].take();}return}let field=&mut self.failures[index];let demand=RetirementDemand{copy_bytes:size_of::<Option<ValueError>>(),release_bytes:release,depth:1,..Default::default()};let call=self.caller.dispatch_cleanup_step(|cx|close_original_retained_step(cx,demand,|_|{field.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))}));self.accept(call);return}
  match self.caller.close_step(){Ok(call)=>match call.result{Ok(RetainedCloneStep::Complete(_))if self.caller.terminal_is_empty()=>self.closed=true,Ok(_)=>{},Err(error)=>{self.root_failure=Some(error);self.failed=true;}},Err(error)=>self.retain(error)}
 }
 fn pump(&mut self,slot:&Slot)->bool{
  let before=(self.caller.retained_spent(),self.caller.fuel_remaining(),self.caller.ready(),self.closed);
  if slot.detached.load(Ordering::Acquire){
   if let Some(task)=self.compiler.as_ref(){if task.can_close()&&self.room(){let call=self.caller.dispatch_cleanup_step(|cx|self.compiler.as_mut().unwrap().close(None,cx));self.accept(call);if self.compiler.as_ref().is_some_and(compiler::CompilerTask::terminal){self.compiler.take();}}}
   else{self.close_one(slot);}
  }else if !self.failed&&self.room()&&!self.caller.ready(){match self.caller.admit_step(){Ok(call)=>if let Err(error)=call.result{self.retain(error)},Err(error)=>self.retain(error)}}
  before!=(self.caller.retained_spent(),self.caller.fuel_remaining(),self.caller.ready(),self.closed)
 }
}

fn with_node<T>(index:usize,generation:u64,visit:impl FnOnce(&mut Node)->T)->Option<T>{let slot=SLOTS.get(index)?;if slot.generation.load(Ordering::Acquire)!=generation{return None}let mut node=match slot.node.try_lock(){Ok(node)=>node,Err(_)=>{RETRY.store(true,Ordering::Release);return None}};if slot.generation.load(Ordering::Relaxed)!=generation{return None}node.as_mut().map(visit)}
fn maintenance()->Result<WorkerMaintenanceTicket,WorkerMaintenanceError>{let mut hook=HOOK.lock().unwrap_or_else(std::sync::PoisonError::into_inner);if let Some(ticket)=*hook{return Ok(ticket)}let ticket=crate::renderer_worker_pool().install_maintenance_hook(Lane::Io,worker,[0,0])?;*hook=Some(ticket);Ok(ticket)}
fn compiler_maintenance()->Result<WorkerMaintenanceTicket,WorkerMaintenanceError>{let mut hook=COMPILER_HOOK.lock().unwrap_or_else(std::sync::PoisonError::into_inner);if let Some(ticket)=*hook{return Ok(ticket)}let ticket=crate::renderer_worker_pool().install_maintenance_hook(Lane::Background,compiler_worker,[0,0])?;*hook=Some(ticket);Ok(ticket)}
fn wake_compiler(){crate::RENDERER_IO_WAKE.store(true,Ordering::Release);if let Err(error)=compiler_maintenance().and_then(|ticket|crate::renderer_worker_pool().request_maintenance(ticket)){let mut failure=SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner);if failure.is_none(){*failure=Some(error);}}}
struct CompilerRunning(&'static Slot);
impl Drop for CompilerRunning{fn drop(&mut self){self.0.compiler_running.store(false,Ordering::Release);if self.0.detached.load(Ordering::Acquire)||self.0.notify_client.load(Ordering::Acquire){wake();}}}
fn compiler_worker(_: [u64;2])->WorkerMaintenanceStep{
 let mut more=false;for slot in &SLOTS{let waker={let Ok(mut state)=slot.node.try_lock()else{more|=slot.compiler_wake.load(Ordering::Acquire);continue};let Some(node)=state.as_mut()else{continue};if !slot.compiler_wake.swap(false,Ordering::AcqRel)||node.failed||slot.compiler_cancelled.load(Ordering::Acquire)||slot.detached.load(Ordering::Acquire)||!node.room(){continue}let Some(task)=node.compiler.as_mut()else{continue};if task.status()!=compiler::Status::Pending{continue}slot.compiler_running.store(true,Ordering::Release);let running=CompilerRunning(slot);let call=node.caller.dispatch_step(|cx|task.poll(cx));node.accept(call);drop(running);more|=slot.compiler_wake.load(Ordering::Acquire);if node.failed||node.compiler.as_ref().is_some_and(|task|matches!(task.status(),compiler::Status::Ready|compiler::Status::BackendRefusal)){slot.waiter.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take()}else{None}};if let Some(waker)=waker{waker.wake();}}if more{WorkerMaintenanceStep::More}else{WorkerMaintenanceStep::Idle}
}
fn wake(){RETRY.store(true,Ordering::Release);crate::RENDERER_IO_WAKE.store(true,Ordering::Release);if let Err(error)=maintenance().and_then(|ticket|crate::renderer_worker_pool().request_maintenance(ticket)){let mut failure=SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner);if failure.is_none(){*failure=Some(error);}}}
fn worker(_: [u64;2])->WorkerMaintenanceStep{RETRY.store(false,Ordering::Release);let mut more=false;for slot in &SLOTS{let waker={let Ok(mut node)=slot.node.try_lock()else{if !slot.compiler_running.load(Ordering::Acquire){RETRY.store(true,Ordering::Release);}continue};if let Some(value)=node.as_mut(){let progress=value.pump(slot);more|=progress;let waker=if progress||value.failed||value.closed||slot.notify_client.swap(false,Ordering::AcqRel){slot.waiter.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take()}else{None};if value.closed&&unsafe{(&*slot.fields.get()).empty_owner()}{node.take();slot.published.store(false,Ordering::Release);}waker}else{None}};if let Some(waker)=waker{waker.wake();}}if more||RETRY.load(Ordering::Acquire){WorkerMaintenanceStep::More}else{WorkerMaintenanceStep::Idle}}

#[derive(Clone,Copy)]
pub struct CreateAppBorrowed<'a>{pub path:&'a Path,pub plugin:&'a str,pub app:&'a str,pub schema:&'a str}
/// 🎟️ The exact request keeps its fixed source and immutable received fields through queue and compiler work.
pub struct CreateAppRequestOwner{index:usize,generation:u64,closing:bool}
impl CreateAppRequestOwner{
 fn claim()->Result<Self,CreateAppSourceFailure>{if let Some(error)=*SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner){return Err(CreateAppSourceFailure{kind:CreateAppSourceFailureKind::Maintenance(error),owner:None,initial:None})}maintenance().map_err(|error|CreateAppSourceFailure{kind:CreateAppSourceFailureKind::Maintenance(error),owner:None,initial:None})?;for(index,slot)in SLOTS.iter().enumerate(){let Ok(mut node)=slot.node.try_lock()else{continue};if node.is_some(){continue}let Some(generation)=slot.generation.load(Ordering::Relaxed).checked_add(1)else{continue};let caller=crate::native_launch::native_compiler_task_caller().map_err(|error|CreateAppSourceFailure{kind:CreateAppSourceFailureKind::Source,owner:None,initial:Some(error)})?;slot.generation.store(generation,Ordering::Release);slot.detached.store(false,Ordering::Release);slot.published.store(false,Ordering::Release);slot.compiler_wake.store(false,Ordering::Release);slot.compiler_cancelled.store(false,Ordering::Release);slot.compiler_running.store(false,Ordering::Release);slot.notify_client.store(false,Ordering::Release);slot.waiter.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();assert!(unsafe{(&*slot.compiler_inputs.get()).terminal()});unsafe{*slot.compiler_output.get()=compiler::Output::empty();}*node=Some(Node::new(caller));return Ok(Self{index,generation,closing:false})}Err(CreateAppSourceFailure{kind:CreateAppSourceFailureKind::RegistryFull,owner:None,initial:None})}
 fn fields(&self)->&Fields{let slot=&SLOTS[self.index];assert!(!self.closing&&slot.generation.load(Ordering::Acquire)==self.generation&&slot.published.load(Ordering::Acquire),"original CreateApp fields require the live published owner");unsafe{&*slot.fields.get()}}
 pub fn path(&self)->&Path{self.fields().path.as_ref().unwrap()}
 pub fn plugin(&self)->&str{self.fields().plugin.as_deref().unwrap()}
 pub fn app(&self)->&str{self.fields().app.as_deref().unwrap()}
 pub fn schema(&self)->&str{self.fields().schema.as_deref().unwrap()}
 pub fn cancel_compiler(&self){let slot=&SLOTS[self.index];if slot.generation.load(Ordering::Acquire)==self.generation{slot.compiler_cancelled.store(true,Ordering::Release);wake();}}
 fn valid(&self)->Result<(),CreateAppSourceFailureKind>{if self.closing{return Err(CreateAppSourceFailureKind::Closed)}if SLOTS[self.index].generation.load(Ordering::Acquire)!=self.generation{return Err(CreateAppSourceFailureKind::Stale)}if let Some(error)=*SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner){return Err(CreateAppSourceFailureKind::Maintenance(error))}Ok(())}
 pub fn into_failure(self,kind:CreateAppSourceFailureKind)->CreateAppSourceFailure{CreateAppSourceFailure{kind,owner:Some(self),initial:None}}
 /// 🏗️ Only the actual initiating caller can admit the sealed compiler frame and its original immutable inputs.
 pub fn start_compiler(&self,runtime:&std::sync::Arc<semio_framework_plugin_host::GuestRuntimes>,hash:semio_framework_actor::PackageHash,bytes:&mut Option<semio_framework_job::OriginalSuppliedJobBytes>)->Result<bool,CreateAppSourceFailureKind>{
  self.valid()?;if SLOTS[self.index].compiler_cancelled.load(Ordering::Acquire){return Err(CreateAppSourceFailureKind::Cancelled)}compiler_maintenance().map_err(CreateAppSourceFailureKind::Maintenance)?;let result=with_node(self.index,self.generation,|node|{if node.failed{return Err(CreateAppSourceFailureKind::Source)}if let Some(task)=node.compiler.as_ref(){return if task.matches(runtime,hash,bytes){Ok(true)}else{node.retain(ValueError::literal(ValueRefusalKind::InvariantViolated,"compiler retry changed its original runtime, package or input custody"));Err(CreateAppSourceFailureKind::Source)}}let call=node.caller.dispatch_step(|cx|compiler::admit(self.index,self.generation,runtime,hash,bytes,&mut node.compiler,cx));match node.accept(call){Some(true)=>{node.compiler.as_mut().unwrap().committed=true;Ok(true)},Some(false)=>{node.retain(ValueError::literal(ValueRefusalKind::WorkLimit,"compiler frame does not fit its unchanged original request stock"));Err(CreateAppSourceFailureKind::Source)},None=>Err(CreateAppSourceFailureKind::Source)}});if matches!(result,Some(Ok(true))){wake_compiler();}else if result.is_none(){wake();}result.unwrap_or(Ok(false))
 }
 /// 🧾️ The full result stays in its original mailbox through receipt, exact frame close and current-source final publication.
 pub fn poll_compiler(&self,waker:&Waker,witness:&std::sync::Arc<semio_framework_plugin_host::GuestRuntimes>,output:&mut Option<semio_framework_plugin_host::CompiledHandle>)->Result<bool,CreateAppSourceFailureKind>{
  self.valid()?;let slot=&SLOTS[self.index];if slot.compiler_cancelled.load(Ordering::Acquire){return Err(CreateAppSourceFailureKind::Cancelled)}*slot.waiter.lock().unwrap_or_else(std::sync::PoisonError::into_inner)=Some(waker.clone());let result=with_node(self.index,self.generation,|node|{
   if node.failed{return Err(CreateAppSourceFailureKind::Source)}let task=node.compiler.as_ref().ok_or(CreateAppSourceFailureKind::Stale)?;if task.status()==compiler::Status::BackendRefusal{return Err(CreateAppSourceFailureKind::Backend)}if task.status()==compiler::Status::Pending{return Ok(false)}
   if !task.prepared(){let call=node.caller.dispatch_step(|cx|node.compiler.as_mut().unwrap().prepare(cx));match node.accept(call){Some(true)=>{node.compiler.as_mut().unwrap().prepare_committed();slot.notify_client.store(true,Ordering::Release);return Ok(false)},Some(false)=>node.retain(ValueError::literal(ValueRefusalKind::WorkLimit,"compiler result preparation does not fit its unchanged original stock")),None=>{}}return Err(CreateAppSourceFailureKind::Source)}
   if !task.frame_closed(){let before=(node.caller.retained_spent(),node.caller.fuel_remaining());let call=node.caller.dispatch_cleanup_step(|cx|node.compiler.as_mut().unwrap().close(Some(witness),cx));if node.accept(call).is_none(){return Err(CreateAppSourceFailureKind::Source)}if before==(node.caller.retained_spent(),node.caller.fuel_remaining()){node.retain(ValueError::literal(ValueRefusalKind::WorkLimit,"compiler frame cleanup has no remaining original stock or work"));return Err(CreateAppSourceFailureKind::Source)}slot.notify_client.store(true,Ordering::Release);return Ok(false)}
   let mut receipt=None;let demand=OriginalConstructionDemand{items:1,copy_bytes:size_of::<Option<semio_framework_plugin_host::CompiledHandle>>(),capacity_bytes:0,release_bytes:0,depth:1};let call=node.caller.dispatch_step(|cx|admit_original_construction(cx,&mut receipt,demand,|_|Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))));match node.accept(call){Some(true)=>{},Some(false)=>{node.retain(ValueError::literal(ValueRefusalKind::WorkLimit,"compiler result publication does not fit its unchanged original stock"));return Err(CreateAppSourceFailureKind::Source)},None=>return Err(CreateAppSourceFailureKind::Source)}assert!(output.is_none(),"compiler consumer must retain one empty original result slot");*output=Some(node.compiler.as_mut().unwrap().take_prepared());node.compiler.take();Ok(true)
  });if slot.notify_client.load(Ordering::Acquire){wake();}else if result.is_none(){slot.notify_client.store(true,Ordering::Release);wake();}result.unwrap_or(Ok(false))
 }
 /// ▶️ The actual request issuer, never its byte supplier, lends the finite compiler producer its original context.
 pub fn dispatch<T:Copy>(&self,body:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<Option<T>,CreateAppSourceFailureKind>{if self.closing{return Err(CreateAppSourceFailureKind::Closed)}if SLOTS[self.index].generation.load(Ordering::Acquire)!=self.generation{return Err(CreateAppSourceFailureKind::Stale)}if let Some(error)=*SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner){return Err(CreateAppSourceFailureKind::Maintenance(error))}let result=with_node(self.index,self.generation,|node|{if node.failed{return Err(CreateAppSourceFailureKind::Source)}let call=node.caller.dispatch_step(body);node.accept(call).map(Some).ok_or(CreateAppSourceFailureKind::Source)});wake();result.unwrap_or(Ok(None))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(slot)=SLOTS.get(self.index){if slot.generation.load(Ordering::Acquire)==self.generation{slot.detached.store(true,Ordering::Release);}}wake();}
 pub fn terminal_is_empty(&self)->bool{self.closing&&(SLOTS[self.index].generation.load(Ordering::Acquire)!=self.generation||SLOTS[self.index].node.try_lock().is_ok_and(|node|node.is_none()))}
}
impl Drop for CreateAppRequestOwner{fn drop(&mut self){self.begin_close();}}
pub struct CreateAppSourceOpen<'a>{input:CreateAppBorrowed<'a>,owner:Option<CreateAppRequestOwner>,completed:bool}
pub fn open_create_app_source(input:CreateAppBorrowed<'_>)->CreateAppSourceOpen<'_>{CreateAppSourceOpen{input,owner:None,completed:false}}
impl Future for CreateAppSourceOpen<'_>{type Output=Result<CreateAppRequestOwner,CreateAppSourceFailure>;fn poll(self:Pin<&mut Self>,context:&mut Context<'_>)->Poll<Self::Output>{let this=self.get_mut();assert!(!this.completed,"completed CreateApp source cannot issue another caller");if this.owner.is_none(){match CreateAppRequestOwner::claim(){Ok(owner)=>this.owner=Some(owner),Err(error)=>{this.completed=true;return Poll::Ready(Err(error))}}}let owner=this.owner.as_ref().unwrap();let slot=&SLOTS[owner.index];if let Some(error)=*SCHEDULER_FAILURE.lock().unwrap_or_else(std::sync::PoisonError::into_inner){this.completed=true;return Poll::Ready(Err(CreateAppSourceFailure{kind:CreateAppSourceFailureKind::Maintenance(error),owner:this.owner.take(),initial:None}))}*slot.waiter.lock().unwrap_or_else(std::sync::PoisonError::into_inner)=Some(context.waker().clone());let result=with_node(owner.index,owner.generation,|node|{node.receive(slot,this.input);if node.failed{Some(false)}else if slot.published.load(Ordering::Acquire){Some(true)}else{None}});wake();match result{Some(Some(true))=>{this.completed=true;Poll::Ready(Ok(this.owner.take().unwrap()))},Some(Some(false))=>{this.completed=true;Poll::Ready(Err(CreateAppSourceFailure{kind:CreateAppSourceFailureKind::Source,owner:this.owner.take(),initial:None}))},_=>Poll::Pending}}}

